/**
 * 数学知识点**精编内容表**（按知识点标题精确索引，优先级高于规则生成）。
 *
 * 为什么要有这一层：`lectures.ts` 是「按标题正则分派」的规则生成器，77 条规则要覆盖 960 个
 * 知识点，必然大面积复用（唯一内容只有 118 组，重复率 87.7%），而且宽泛规则会遮蔽专用规则，
 * 造成知识点挂错内容（如「二重极限」拿到一元左右极限、「莱布尼茨公式」拿到牛顿—莱布尼茨公式）。
 * 精编内容按标题**精确命中**，命中即不再走规则，因此：
 *   - 内容与知识点一一对应，不再复用；
 *   - 每写一个，覆盖率就涨一点（构建时会打印）。
 *
 * 写作口径：
 *   - `explanation` 的第一句会被截成页面上显示的 `summary`（30~80 字），所以**第一句必须自成一句结论**；
 *   - `keyPoints` 写成**有信息量的判断句**（会被截成小标题 + 正文），不要复读标题；
 *   - `formula` 就是页面上的「锚点」，用课程里通用的记号；
 *   - `example` 必须带具体数字或可验证的结论；
 *   - `trap` 写学生真会踩的坑，不写「要细心」这类废话；
 *   - **不写课程/老师/例题编号**（合规要求，见《数学知识点校验报告.md》）。
 *
 * **重名标题必须限定章节**：键写成 `章节标题/知识点标题`（如 `一维随机变量及其分布/定义`），
 * 因为 `定义` 这类标题在全库出现 22 次，只按标题索引会把内容套到别的章节。
 * `tools/check-math-content.mjs` 会断言「不带 / 的键在全库唯一」，重名就会失败。
 *
 * 用法：写完跑 `cd tools && npm run build:content && npm run validate:content`，
 * 再跑 `node tools/check-math-content.mjs`（关键映射断言）与 `python tools/_math_audit.py`（覆盖率）。
 */
import type { MathLecture, MathVisualKind } from './lectures'

type LectureBody = Omit<MathLecture, 'title'>

