    keyPoints: [
      'P{|X−EX|≥ε} ≤ D(X)/ε²，其中 ε 是任意正数',
      '方差越小，偏离均值超过 ε 的概率上界越小',
      '只要 EX 与 DX 存在就能用，不需要具体分布',
    ],
    visual: 'probability',
