    steps: ['先判断是否独立（看联合分布能否拆开）', '再算协方差判断是否不相关', '题目说明是二维正态时两者可互推'],
    formula: '独立 ⇒ ρ=0；二维正态下 ρ=0 ⇒ 独立',
